import pandas as pd
import numpy as np

def clean(df):
    df = df.copy()
    # strip whitespace from object columns
    for col in df.select_dtypes(include='object').columns:
        df[col] = df[col].astype(str).str.strip()
        df[col] = df[col].replace({'nan': np.nan, 'None': np.nan, '': np.nan})
    # numeric conversion for columns that should be numeric
    for col in ['bill_length_mm','bill_depth_mm','flipper_length_mm','body_mass_g','year']:
        if col in df.columns:
            df[col] = pd.to_numeric(df[col], errors='coerce')
    # fix flipper_length_mm negative values
    if 'flipper_length_mm' in df.columns:
        df['flipper_length_mm'] = df['flipper_length_mm'].abs()
    # fix body_mass_g outliers, e.g. 5050000 -> 5050
    if 'body_mass_g' in df.columns:
        mask = df['body_mass_g'] > 6500
        df.loc[mask, 'body_mass_g'] = df.loc[mask, 'body_mass_g'] / 1000.0
        df.loc[df['body_mass_g'] < 2500, 'body_mass_g'] = np.nan
        df.loc[df['body_mass_g'] > 6500, 'body_mass_g'] = np.nan
    return df

def answer(df):
    dfc = clean(df)
    sums = dfc.groupby('species')['body_mass_g'].sum(min_count=1)
    return {str(k): float(v) for k, v in sums.items()}
